package org.pms.silverocean.controller;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.pms.silverocean.common.ResponseCode;import org.pms.silverocean.controller.wrappers.ResponseDTO;import org.pms.silverocean.service.I18NService;import org.pms.silverocean.service.estateops.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/estate/operations")@RequiredArgsConstructor public class EstateOperationsController{private final EstateOperationsService service;private final I18NService i18n;@PostMapping("/budgets")ResponseEntity<ResponseDTO>budget(@RequestBody@Valid EstateOperationsModels.BudgetCreate r){return ok(service.createBudget(r));}@PostMapping("/budgets/{id}/lines")ResponseEntity<ResponseDTO>line(@PathVariable long id,@RequestBody@Valid EstateOperationsModels.BudgetLineCreate r){return ok(service.addLine(id,r));}@PutMapping("/budgets/{id}/approve")ResponseEntity<ResponseDTO>approve(@PathVariable long id){return ok(service.approve(id));}@PutMapping("/budgets/{id}/close")ResponseEntity<ResponseDTO>close(@PathVariable long id){return ok(service.close(id));}@PutMapping("/budget-lines/{id}/actual")ResponseEntity<ResponseDTO>actual(@PathVariable long id,@RequestBody@Valid EstateOperationsModels.Actual r){return ok(service.actual(id,r));}@GetMapping("/properties/{id}/budgets")ResponseEntity<ResponseDTO>budgets(@PathVariable long id){return ok(service.budgetList(id));}@PostMapping("/meetings")ResponseEntity<ResponseDTO>meeting(@RequestBody@Valid EstateOperationsModels.MeetingCreate r){return ok(service.createMeeting(r));}@PutMapping("/meetings/{id}")ResponseEntity<ResponseDTO>meetingUpdate(@PathVariable long id,@RequestBody@Valid EstateOperationsModels.MeetingUpdate r){return ok(service.updateMeeting(id,r));}@GetMapping("/properties/{id}/meetings")ResponseEntity<ResponseDTO>meetings(@PathVariable long id){return ok(service.meetingList(id));}@PostMapping("/meetings/{id}/resolutions")ResponseEntity<ResponseDTO>resolution(@PathVariable long id,@RequestBody@Valid EstateOperationsModels.ResolutionCreate r){return ok(service.createResolution(id,r));}@PutMapping("/resolutions/{id}")ResponseEntity<ResponseDTO>resolutionUpdate(@PathVariable long id,@RequestBody@Valid EstateOperationsModels.ResolutionUpdate r){return ok(service.updateResolution(id,r));}@GetMapping("/meetings/{id}/resolutions")ResponseEntity<ResponseDTO>resolutions(@PathVariable long id){return ok(service.resolutionList(id));}@PostMapping("/work-orders")ResponseEntity<ResponseDTO>work(@RequestBody@Valid EstateOperationsModels.WorkCreate r){return ok(service.createWork(r));}@PutMapping("/work-orders/{id}")ResponseEntity<ResponseDTO>workUpdate(@PathVariable long id,@RequestBody@Valid EstateOperationsModels.WorkUpdate r){return ok(service.updateWork(id,r));}@GetMapping("/properties/{id}/work-orders")ResponseEntity<ResponseDTO>works(@PathVariable long id){return ok(service.workList(id));}private ResponseEntity<ResponseDTO>ok(Object v){return ResponseEntity.ok(new ResponseDTO(true,ResponseCode.GENERAL_SUCCESS.getCode(),i18n.getLocalizedMessage(ResponseCode.GENERAL_SUCCESS),v));}}
